.count-badge {
  position: relative;
  display: inline-flex;
}
.count-badge-marker {
  position: absolute;
  inset-block-start: 0;
  inset-inline-end: 0;
  transform: translate(40%, -40%);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  /* A CIRCLE AT ONE DIGIT, A PILL AT TWO — and nothing in between.
   * The box was `min-inline-size: var(--space-4)` with padding on both sides
   * and a 2px ring, so a single digit measured 16 tall and 19 wide: an egg on
   * every bell in the system (owner, 2026-08-24, and the box model agrees —
   * 4+4 padding + 2+2 border + ~7 of glyph). The padding is what does not
   * belong at one character: the min size already reserves the room. */
  min-inline-size: var(--space-4);
  block-size: var(--space-4);
  border-radius: var(--radius-full);
  border: 2px solid var(--background);
  background: var(--destructive);
  color: var(--destructive-foreground);
  font-size: var(--font-xs);
  font-weight: var(--font-weight-semibold);
  font-variant-numeric: tabular-nums;
  line-height: 1;
}
.count-badge-marker[data-wide] { padding-inline: var(--space-1); }
.count-badge-marker[data-tone='primary']  { background: var(--primary);  color: var(--primary-foreground); }
.count-badge-marker[data-tone='success']  { background: var(--success);  color: var(--success-foreground); }
.count-badge-marker[data-dot] {
  min-inline-size: 0;
  inline-size: var(--space-3);
  block-size: var(--space-3);
  padding: 0;
}
.count-badge .sr-only {
  position: absolute;
  width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0;
}

import './CountBadge.css'
import { type ReactNode } from 'react'
import { cn } from '../lib/cn'

type Tone = 'primary' | 'danger' | 'success'

type Props = {
  /** The element the marker sits on (an Icon, IconButton, Avatar). */
  children: ReactNode
  /** Numeric count. Values over `max` render as `${max}+`. Omit for a plain dot. */
  count?: number
  /** Show a small dot with no number (e.g. "unread", "online"). */
  dot?: boolean
  max?: number
  /** What the count MEANS, never how big it is: `primary` there is something here, `danger`
   *  something is wrong, `success` something finished. A count that reddens as it grows blames
   *  the number.
   */
  tone?: Tone
  /** Read out to a screen reader, e.g. "3 unread". Without it the marker is
   *  decorative (aria-hidden) — pass it whenever the count carries meaning. */
  label?: string
  className?: string
}

/* A count or dot pinned to the top-inline-end corner of whatever it wraps —
 * notifications on a bell, unread on an avatar. Distinct from <Badge>, which is
 * a standalone status pill. Hidden entirely when count is 0 and no dot. 
   *
   * Copy: the accessible label counts the thing, not the badge — "3 unread
   * messages". A number alone is read as "three" with nothing to attach it
   * to.
   */
export function CountBadge({ children, count, dot, max = 99, tone = 'danger', label, className }: Props) {
  const show = dot || (count !== undefined && count > 0)
  const text = count !== undefined ? (count > max ? `${max}+` : String(count)) : ''
  return (
    <span className={cn('count-badge', className)}>
      {children}
      {show && (
        <span className="count-badge-marker" data-tone={tone} data-dot={dot || undefined} data-wide={text.length > 1 || undefined} aria-hidden={label ? undefined : 'true'}>
          {!dot && text}
          {label && <span className="sr-only">{label}</span>}
        </span>
      )}
    </span>
  )
}
